import{describe,it,expect}from"vitest";import{indiasFirstsData,firstsQuizQuestions,getFirstById,filterFirsts,getTimelineFirsts,evaluateQuizAnswer}from"../../frontend/indias-firsts/indias-firsts.js";const MANDATORY_FIRST_IDS=["first-satellite","first-woman-pm","first-metro","first-iit","first-high-court","first-nobel-laureate","first-national-park"];describe("Indias Firsts Dataset Coverage & Mandatory Examples",()=>{it("contains at least 7 major firsts (contains 10)",()=>{expect(indiasFirstsData.length).toBeGreaterThanOrEqual(7)}),it("includes all mandatory firsts from issue description",()=>{const e=indiasFirstsData.map(e=>e.id.toLowerCase());MANDATORY_FIRST_IDS.forEach(t=>{expect(e).toContain(t)})}),it("every item contains required fields with valid details",()=>{indiasFirstsData.forEach((e,t)=>{expect(e,`Item at index ${t} missing id`).toHaveProperty("id"),expect(e,`Item at index ${t} missing title`).toHaveProperty("title"),expect(e,`Item at index ${t} missing name`).toHaveProperty("name"),expect(e,`Item at index ${t} missing year`).toHaveProperty("year"),expect(e,`Item at index ${t} missing category`).toHaveProperty("category"),expect(e,`Item at index ${t} missing description`).toHaveProperty("description"),expect(e,`Item at index ${t} missing details`).toHaveProperty("details"),expect(typeof e.year).toBe("number"),expect(e.year).toBeGreaterThan(1800),expect(e.year).toBeLessThan(2030)})}),it("all item IDs are unique",()=>{const e=indiasFirstsData.map(e=>e.id);expect(new Set(e).size).toBe(e.length)})}),describe("Chronological Timeline Engine",()=>{it("sorts firsts chronologically from earliest to latest",()=>{const e=getTimelineFirsts();expect(e.length).toBe(indiasFirstsData.length),expect(e[0].year).toBe(1853);for(let t=0;t<e.length-1;t++)expect(e[t].year).toBeLessThanOrEqual(e[t+1].year)})}),describe("Quiz Mode & Answer Evaluation Engine",()=>{it("contains at least 5 multiple-choice quiz questions with 4 options each",()=>{expect(firstsQuizQuestions.length).toBeGreaterThanOrEqual(5),firstsQuizQuestions.forEach((e,t)=>{expect(e,`Quiz question ${t} missing question`).toHaveProperty("question"),expect(e,`Quiz question ${t} missing options`).toHaveProperty("options"),expect(e,`Quiz question ${t} missing correctIndex`).toHaveProperty("correctIndex"),expect(e,`Quiz question ${t} missing explanation`).toHaveProperty("explanation"),expect(Array.isArray(e.options)).toBe(!0),expect(e.options.length).toBe(4),expect(e.correctIndex).toBeGreaterThanOrEqual(0),expect(e.correctIndex).toBeLessThan(4)})}),it("evaluates quiz answers correctly for right and wrong options",()=>{const e=evaluateQuizAnswer(0,1);expect(e.isCorrect).toBe(!0),expect(e.explanation).toContain("Aryabhata");const t=evaluateQuizAnswer(0,0);expect(t.isCorrect).toBe(!1),expect(t.correctOption).toBe("Aryabhata")}),it("returns invalid object for out-of-range question index",()=>{const e=evaluateQuizAnswer(99,0);expect(e.isCorrect).toBe(!1)})}),describe("Query & Search Filters",()=>{it("retrieves item profile by ID or partial name",()=>{const e=getFirstById("first-satellite");expect(e).toBeDefined(),expect(e.name).toBe("Aryabhata");const t=getFirstById("Tagore");expect(t).toBeDefined(),expect(t.id).toBe("first-nobel-laureate")}),it("filters firsts by search query (e.g. Kharagpur or Indira)",()=>{const e=filterFirsts("Kharagpur");expect(e.length).toBe(1),expect(e[0].name).toBe("IIT Kharagpur");const t=filterFirsts("Indira");expect(t.length).toBeGreaterThan(0)}),it("filters firsts by category tag",()=>{const e=filterFirsts("","science");expect(e.length).toBeGreaterThanOrEqual(2)}),it("returns empty array when search query matches nothing",()=>{const e=filterFirsts("NonExistentFirstXYZ");expect(e).toEqual([])})});